"""
    Parse a list of `strings` and return the "best" element based on `criteria`.

    :param strings: List of string where best will be found based on `criteria`.
    :type strings: List[str]
    :param criteria: '>'-separated substrings sought in descending order.
        '+' is a logical 'and', '=' substitutes: `A=B` returns B if A is found.
    :type criteria: str
    :return: Best string based on given `criteria` or `` if no best found.
    :rtype: str
    """
def find_best(strings: Any, criteria: Any) -> object {
    (criterion, _, further_criteria) = criteria.partition('>');
    wanted = criterion.partition('=')[0].split('+');
    if all(((w in strings) or (w is '')) for w in wanted) {
        return criterion.rpartition('=')[2];
    } else {
        return find_best(strings, further_criteria);
    }
}

"""
    Convert HSV to RGB (based on colorsys.py).

        Args:
            h (float): Hue 0 to 1.
            s (float): Saturation 0 to 1.
            v (float): Value 0 to 1 (Brightness).
    """
def hsv_to_rgb(h: Any, s: Any, v: Any) -> object {
    if (s == 0.0) {
        return (v, v, v);
    }
    i = int((h * 6.0));
    f = (h * 6.0) - i;
    p = v * (1.0 - s);
    q = v * (1.0 - (s * f));
    t = v * (1.0 - (s * (1.0 - f)));
    i = i % 6;
    v = int((v * 255));
    t = int((t * 255));
    p = int((p * 255));
    q = int((q * 255));
    if (i == 0) {
        return (v, t, p);
    }
    if (i == 1) {
        return (q, v, p);
    }
    if (i == 2) {
        return (p, v, t);
    }
    if (i == 3) {
        return (p, q, v);
    }
    if (i == 4) {
        return (t, p, v);
    }
    if (i == 5) {
        return (v, p, q);
    }
}

""" Function to parse the json response from the references collection
    in Solr. It returns the results as a list with the annotation and details.
    """
def parse_refs_json(data: Any) -> object {
    docs = data['response']['docs'];
    results = [
        [docs[i].get('annotation'), docs[i].get('details')[0]]
        for i in range(len(data['response']['docs']))
    ];
    return results;
}

""" get the file names for eval """
def _get_file_names(eval_file_idx: Any) -> object {
    file_names = {};
    train_files_idx_list = [1, 2, 3, 4, 5];
    train_files_idx_list.remove(eval_file_idx);
    print('Setting idx \'{}\' as validation/eval data.'.format(eval_file_idx));
    file_names['train'] = [('data_batch_%d' % i) for i in train_files_idx_list];
    file_names['eval'] = [('data_batch_' + str(eval_file_idx))];
    file_names['test'] = ['test_batch'];
    return file_names;
}

"""
    Get an attribute from a dictionary given its key name.
    :param attribute_name: Attribute name.
    :param json_response: Dictionary where the attribute should be.
    :param default: Value that has to be returned if the attribute is not there.
    :return: Attribute value.
    """
def get(attribute_name: Any, json_response: Any, `default: Any = None) -> object {
    return `default
        if (not json_response or (attribute_name not in json_response))
        else json_response[attribute_name];
}

